const QM = Object.assign(Object.create(null), Object.fromEntries(Q.map(q=>[q.id,q])));
const topicOf = q => TM[q.id[0]];

/* ---------- answer checking ---------- */
function clean(s){return String(s).replace(/\s+/g,'').replace(/[₀-₉]/g,c=>String(c.charCodeAt(0)-8320))}
function counts(s){if(!/^([A-Z][a-z]?\d*)+$/.test(s))return null;const m={};s.replace(/([A-Z][a-z]?)(\d*)/g,(x,e,n)=>{m[e]=(m[e]||0)+(n?+n:1)});return JSON.stringify(Object.keys(m).sort().map(k=>[k,m[k]]))}
function match(v,ans,n){
  v=String(v||'').trim(); if(!v) return false;
  if(n==='num'){const x=parseFloat(v.replace(',','.'));return ans.some(a=>Math.abs(x-a)<1e-9)}
  if(n==='cfg'){const c=v.replace(/[^\d]+/g,',').replace(/^,+|,+$/g,'');return ans.includes(c)}
  if(n==='any'){const c=counts(clean(v));return c!==null&&ans.some(a=>counts(a)===c)}
  return ans.includes(clean(v));
}
function solution(q){
  if(q.t==='mc') return R(q.o[q.a]);
  if(q.t==='in') return (q.n==='num'||q.n==='cfg')? R('{'+q.a[0]+'}') : R('{'+q.a[0]+'}');
  if(q.t==='multi') return q.f.map(f=>f.l+': '+R('{'+f.a[0]+'}')).join(' · ');
  if(q.t==='sort') return q.bins.map((b,i)=>'<b>'+b+':</b> '+q.items.filter(x=>x[1]===i).map(x=>R(x[0])).join(', ')).join('<br>');
  if(q.t==='pick') return q.a.map(i=>R(q.items[i])).join(', ');
  return '';
}

